"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[3242],{90583(e){e.exports=JSON.parse('{"tag":{"label":"tsp","permalink":"/azeon/p-vs-np/tags/tsp","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"heuristics/local-search-algorithms","title":"Local Search Algorithms","description":"Start with any solution, even a terrible random one. Make a small change. Keep it if it helps. Repeat until nothing helps. That\'s local search, it powers a huge amount of real-world optimisation, and its one big weakness is getting stuck.","permalink":"/azeon/p-vs-np/heuristics/local-search-algorithms"},{"id":"real-world-impact/supply-chain-logistics","title":"Supply Chain Logistics","description":"Every parcel van starts the morning with a Traveling Salesman Problem plus extra rules. Companies can\'t solve it perfectly, so they solve it well, and the gap between \'good\' and \'best\' is measured in millions of kilometres.","permalink":"/azeon/p-vs-np/real-world-impact/supply-chain-logistics"},{"id":"np-completeness/the-traveling-salesman-problem","title":"The Traveling Salesman Problem","description":"Write a number on every road from the last post and ask for the shortest round trip. That one change gives you the most famous hard problem in computer science, and a reduction you can do in your head.","permalink":"/azeon/p-vs-np/np-completeness/the-traveling-salesman-problem"},{"id":"heuristics/tsp-and-the-triangle-inequality","title":"TSP and the Triangle Inequality","description":"General TSP can\'t be approximated at all. Add one sensible rule, that going direct is never longer than taking a detour, and a spanning tree gives a tour within twice the best. Christofides\' 1976 trick gets that to 1.5.","permalink":"/azeon/p-vs-np/heuristics/tsp-and-the-triangle-inequality"}],"unlisted":false}}')}}]);